/bin/bash -c "cat > tmp/pdfs/HexPatchCheck.java <<'JAVA'
import java.math.BigInteger;

public class HexPatchCheck {
    // Transcription of Figure 23's hexadecimal branch; inputs below use the 0x prefix.
    static Number figure23(String str) {
        int pfxLen = 2;
        boolean foundFirstNonZero = false;
        int leadingZeroCount = 0;
        int significantHexDigits = 0;
        for (int i = pfxLen; i < str.length(); i++) {
            char currentChar = str.charAt(i);
            if ("'!foundFirstNonZero && currentChar == '"'0') {
                leadingZeroCount++;
            } else if ("'!foundFirstNonZero && currentChar != '"'0') {
                foundFirstNonZero = true;
            }
            if (foundFirstNonZero) {
                significantHexDigits++;
            }
        }
        final int hexDigits = significantHexDigits;
        if (hexDigits > 16 || (hexDigits == 16 && ("'!foundFirstNonZero || str.charAt(pfxLen + leadingZeroCount + 15) > '"'7'))) {
            return new BigInteger(str.substring(pfxLen), 16);
        }
        if (hexDigits > 8 || (hexDigits == 8 && ("'!foundFirstNonZero || str.charAt(pfxLen + leadingZeroCount + 7) > '"'7'))) {
            return Long.decode(str);
        }
        return Integer.decode(str);
    }
    public static void main(String[] args) {
        for (String s : new String[]{\"0x8000\", \"0x7FFFFFFF\", \"0x80000000\", \"0x8000000000000000\"}) {
            try {
                Number value = figure23(s);
                System.out.println(s + \" -> \" + value.getClass().getSimpleName() + \" \" + value);
            } catch (NumberFormatException e) {
                System.out.println(s + \" -> NumberFormatException: \" + e.getMessage());
            }
        }
    }
}
